// CSD_RATIONALE_BEGIN
// Diagnosis: previous attempt hit 15% accuracy. The main failure pattern from
// the rollouts is that Qwen wrote `y / d * t` when the ground truth needed
// `y//d*t` (Python integer division). Several other failures are formula
// errors and a few are nested `<<` inside `<<>>` spans. The strategy itself
// is fine; the levers are prompt guidance and a soft preference for `//`
// inside constrained spans, plus a penalty on `<<` inside an active span so
// we don't nest.
// Changes vs. previous attempt:
//   1. Stronger task guidance specifying Python-style `//` integer division,
//      using exact variable names from the problem template, and the
//      one-expression-per-<<>> convention.
//   2. Inside the constrained span, use SafeBoostedConstrainedStep biased
//      toward `//` (and away from `<<`) so when `/` and `//` are both
//      legal the model prefers integer division and avoids re-opening.
//   3. Keep chunked outside-span generation for speed.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: Outside the span the implication is vacuous; we set
//   currentConstrainedOut := [] only when UnconstrainedChunk stopped on
//   "<<", and [] is parser-valid by precondition. CloseConstrainedSpan
//   flips insideConstrainedOut to false. SafeBoostedConstrainedStep returns
//   EOS (we break) or a parser-valid next token, and AppendConstrainedToken
//   carries that validity into currentConstrainedOut.
// progress: UnconstrainedChunk grows generated by <= stepsUsed and steps by
//   stepsUsed. Other branches add one step and at most one token. Hence
//   |generated| <= |generatedPrefix| + steps holds throughout.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "You are solving a SYMBOLIC math word problem: variable names in braces like {n}, {t}, {d} are literal symbol names, not numbers. Solve step by step. Wrap every arithmetic expression inline using << >> delimiters. Use Python-style integer division `//` (NOT `/`) for any division between whole quantities, and use `*` for multiplication. Do not nest << inside another << >>. Each <<...>> must contain exactly one expression with no `=`. Use the exact variable names from the problem. Finish with a single line: #### <<final_expression>>. Example: if the answer is y divided by d times t, write <<y//d*t>>.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remaining: nat := maxSteps - steps;
    var chunkBudget: nat := if remaining < 32 then remaining else 32;
    var chunkedG, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedG;
    steps := steps + stepsUsed;
    if stoppedEos {
      break;
    } else if stoppedOpen {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    } else if stepsUsed == 0 {
      break;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    // Soft penalty on tokens that lead to nested spans or float division.
    var nextPen := helpers.SafePenalizedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, ["<<", "<", "="], 6.0, eosToken
    );
    steps := steps + 1;
    if nextPen == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, nextPen
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

